// Package: Microsoft.Extensions.AI
// Package: Microsoft.Extensions.AI.Azure --version 9.*
// End-to-end RAG orchestration using provider-agnostic abstractions with Azure OpenAI.

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Azure;

public sealed class RagService
{
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embeddingGenerator;
    private readonly IVectorStore _vectorStore;
    private readonly IChatClient _chatClient;

    public RagService(
        IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator,
        IVectorStore vectorStore,
        IChatClient chatClient)
    {
        _embeddingGenerator = embeddingGenerator ?? throw new ArgumentNullException(nameof(embeddingGenerator));
        _vectorStore = vectorStore ?? throw new ArgumentNullException(nameof(vectorStore));
        _chatClient = chatClient ?? throw new ArgumentNullException(nameof(chatClient));
    }

    public async Task<string> AnswerAsync(
        string question,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(question);

        var queryResult = await _embeddingGenerator.GenerateAsync(question, ct);
        var queryVector = queryResult.Vector;

        var candidates = await _vectorStore.SearchAsync(
            queryVector,
            topK: 5,
            ct: ct);

        var context = string.Join(
            "\n---\n",
            candidates.Select(c => $"[Source {c.Record.DocumentId}] {c.Record.Text}"));

        var prompt = $"""
System: Answer the question using only the context below. Cite sources using [Source X].

Context:
{context}

Question:
{question}
""";

        var messages = new[]
        {
            new ChatMessage(ChatRole.System, "You are a helpful assistant that answers accurately and cites sources."),
            new ChatMessage(ChatRole.User, prompt)
        };

        var response = await _chatClient.GetResponseAsync(messages, ct);

        return response.Messages.Last().Text ?? string.Empty;
    }
}

